INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2019s-am-21','exam-sg','利用者認証・CAPTCHA','standard','single_choice','【平成31年度 春期 午前 問21】Webサイトで利用されるCAPTCHAに該当するものはどれか。','[{"id":"a","text":"人からのアクセスであることを確認できるよう，アクセスした者に応答を求め，その応答を分析する仕組み"},{"id":"b","text":"不正なSQL文をデータベースに送信しないよう，Webサーバに入力された文字列をプレースホルダに割り当ててSQL文を組み立てる仕組み"},{"id":"c","text":"利用者が本人であることを確認できるよう，Webサイトから一定時間ごとに異なるパスワードを要求する仕組み"},{"id":"d","text":"利用者が本人であることを確認できるよう，Webサイト側で生成した乱数を利用者に送り，利用者側でその乱数を鍵としてパスワードを暗号化して送り返す仕組み"}]','"a"','CAPTCHAはアクセス主体が人間か自動プログラムかを判別するための仕組み。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-22','exam-sg','端末セキュリティ・ストレージ保護','standard','single_choice','【平成31年度 春期 午前 問22】利用者PCの内蔵ストレージが暗号化されていないとき，攻撃者がストレージを抜き取り，自分のPCに接続して情報を盗む攻撃への対策はどれか。','[{"id":"a","text":"内蔵ストレージにインストールしたOSの利用者アカウントにログインパスワードを設定する"},{"id":"b","text":"内蔵ストレージに保存したファイルの読取り権限を，ファイルの所有者だけに付与する"},{"id":"c","text":"利用者PC上でHDDパスワードを設定する"},{"id":"d","text":"利用者PCにBIOSパスワードを設定する"}]','"c"','ストレージを別PCに接続されるとOSのログインパスワードやファイル権限は迂回される。ストレージ自体の保護が必要。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-23','exam-sg','メールセキュリティ・S/MIME','standard','single_choice','【平成31年度 春期 午前 問23】A氏からB氏に電子メールを送る際のS/MIMEの利用に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"A氏はB氏の公開鍵を用いることなく，B氏だけが閲覧可能な暗号化電子メールを送ることができる"},{"id":"b","text":"B氏は受信した電子メールに記載されている内容が事実であることを，公的機関に問い合わせることによって確認できる"},{"id":"c","text":"B氏は受信した電子メールの内容はA氏が署名したものであり，第三者による改ざんはないことを確認できる"},{"id":"d","text":"マルウェアに感染したファイルを添付して送信した場合，B氏が添付ファイルを開いても感染を防ぐことができる"}]','"c"','S/MIMEの電子署名は送信者の署名とメール内容の完全性を検証できるが，内容の真実性やマルウェア感染を保証しない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-24','exam-sg','電子署名・XML署名','standard','single_choice','【平成31年度 春期 午前 問24】XML署名を利用することによってできることはどれか。','[{"id":"a","text":"TLSにおいてHTTP通信の暗号化及び署名の付与に利用し，通信経路上でのXMLファイルの盗聴を防止する"},{"id":"b","text":"XMLとJavaScriptの非同期HTTP通信機能を使い，Webページの内容を動的に書き換えた上で署名を付与し，対話型Webページを作成する"},{"id":"c","text":"XML文書全体に対する単一の署名だけでなく，文書の一部に対する部分署名や多重署名などの複雑な要件に対応する"},{"id":"d","text":"隠したい署名データを画像データの中に埋め込み，署名の存在自体を外から判別できなくする"}]','"c"','XML署名は文書全体だけでなく部分や複数署名などにも対応する。通信路の暗号化はTLS，画像内に情報を隠すのはステガノグラフィ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-25','exam-sg','データベース・最小権限の原則','standard','single_choice','【平成31年度 春期 午前 問25】データベースのアカウントの種類とそれに付与する権限の組合せのうち，情報セキュリティ上，適切なものはどれか。','[{"id":"a","text":"データ構造の定義用アカウント：レコード更新権限有，テーブル作成・削除権限無"},{"id":"b","text":"データ構造の定義用アカウント：レコード更新権限無，テーブル作成・削除権限有"},{"id":"c","text":"データの入力・更新用アカウント：レコード更新権限有，テーブル作成・削除権限有"},{"id":"d","text":"データの入力・更新用アカウント：レコード更新権限無，テーブル作成・削除権限有"}]','"b"','最小権限の原則により，データ構造の定義用はテーブル作成・削除権限を持ち，日常のレコード更新権限は不要。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-26','exam-sg','メッセージ認証符号・MAC','standard','single_choice','【平成31年度 春期 午前 問26】メッセージ認証符号の利用目的に該当するものはどれか。','[{"id":"a","text":"メッセージが改ざんされていないことを確認する"},{"id":"b","text":"メッセージの暗号化方式を確認する"},{"id":"c","text":"メッセージの概要を確認する"},{"id":"d","text":"メッセージの秘匿性を確保する"}]','"a"','MACは共有秘密鍵を使ってメッセージの完全性を確認する。内容を隠す秘匿性は暗号化の役割。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-27','exam-sg','暗号技術・楕円曲線暗号','standard','single_choice','【平成31年度 春期 午前 問27】楕円曲線暗号の特徴はどれか。','[{"id":"a","text":"RSA暗号と比べて，短い鍵長で同レベルの安全性が実現できる"},{"id":"b","text":"共通鍵暗号方式であり，暗号化や復号の処理を高速に行うことができる"},{"id":"c","text":"総当たりによる解読が不可能なことが数学的に証明されている"},{"id":"d","text":"データを秘匿する目的で用いる場合，復号鍵を秘密にしておく必要がない"}]','"a"','楕円曲線暗号は公開鍵暗号方式の一つで，RSAより短い鍵長で同程度の安全性を実現できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-28','exam-sg','暗号技術・ハイブリッド暗号','standard','single_choice','【平成31年度 春期 午前 問28】OpenPGPやS/MIMEにおいて用いられるハイブリッド暗号方式の特徴はどれか。','[{"id":"a","text":"暗号通信方式としてIPsecとTLSを選択可能にすることで利便性を高める"},{"id":"b","text":"公開鍵暗号方式と共通鍵暗号方式を組み合わせ，鍵管理コストと処理性能の両立を図る"},{"id":"c","text":"複数の異なる共通鍵暗号方式を組み合わせて処理性能を高める"},{"id":"d","text":"複数の異なる公開鍵暗号方式を組み合わせて安全性を高める"}]','"b"','データ本体は高速な共通鍵暗号で暗号化し，共通鍵の配送には公開鍵暗号を使う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-29','exam-sg','セキュアプロトコル・SSH公開鍵認証','standard','single_choice','【平成31年度 春期 午前 問29】利用者PC上のSSHクライアントからサーバに公開鍵認証方式でSSH接続するとき，利用者のログイン認証時にサーバが使用する鍵とSSHクライアントが使用する鍵の組合せはどれか。','[{"id":"a","text":"サーバに登録されたSSHクライアントの公開鍵／利用者PC上のSSHクライアントの公開鍵"},{"id":"b","text":"サーバに登録されたSSHクライアントの公開鍵／利用者PC上のSSHクライアントの秘密鍵"},{"id":"c","text":"サーバに登録されたSSHクライアントの秘密鍵／利用者PC上のSSHクライアントの公開鍵"},{"id":"d","text":"サーバに登録されたSSHクライアントの秘密鍵／利用者PC上のSSHクライアントの秘密鍵"}]','"b"','SSH公開鍵認証ではサーバに登録した公開鍵で検証し，クライアントは手元の秘密鍵を使う。秘密鍵をサーバへ渡さない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-30','exam-sg','ネットワークセキュリティ・ハニーポット','standard','single_choice','【平成31年度 春期 午前 問30】侵入者やマルウェアの挙動を調査するために，意図的に脆弱性をもたせたシステム又はネットワークはどれか。','[{"id":"a","text":"DMZ"},{"id":"b","text":"SIEM"},{"id":"c","text":"ハニーポット"},{"id":"d","text":"ボットネット"}]','"c"','ハニーポットは攻撃者を誘い込み，侵入者やマルウェアの挙動を観察・分析するための仕組み。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja');
